1	package release
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11	)
12	
13	// 本文件是“已保存的成功开始执行请求的返回结果必须对应原请求所指批次第一次
14	// 开始执行时的内容”的回归保障：批次用请求编号开始执行后，按原编号、原内容
15	// 再次提交 StartBatch，只能取回第一次开始时的结果（执行中、空投料、零实投、
16	// 差额为应投量的负值）。台账里保存的开始结果即使变成 null、空对象，或被改成
17	// 另一批次的结果、被改掉配方绑定/份数/状态，或混入了批次后来的投料与关闭
18	// 现状，也不能被当作成功结果返回——打开台账及之后的每次查询/写入重载，都
19	// 必须核对保存结果与原请求所指批次（必须存在且当前为执行中或已关闭）第一
20	// 次开始时的内容一致；不一致按 ErrCorruptData 拒绝整份台账，不删除请求、
21	// 不补造批次，也不用当前查询结果覆盖损坏结果。
22	
23	// setupStartRequestLedger 在 dir 建立一份正常台账：
24	//   - B1（已关闭）：创建时用 R1/v1、5 份，草稿调整为 R1/v2、3 份后由
25	//     start-b1 开始，随后登记两条投料（f1、f2）并由 close-b1 关闭——
26	//     其保存的开始结果必须是首次开始时的内容（R1/v2、3 份、执行中、
27	//     空投料），不能混入后来的投料与关闭现状；
28	//   - B2（执行中）：与 B1 相同的最终配方与份数，start-b2 开始，无投料——
29	//     其保存结果与 B1 的首次开始结果仅批次编号不同，用于验证另一批次的
30	//     结果不能顶替；
31	//   - B3（执行中）：R1/v1、2 份，无投料的正常批次，用于验证损坏的开始
32	//     请求不能被“本次访问的是另一个正常批次”绕过。
33	//
34	// 返回落盘后的台账文件内容，供各用例改坏后重写。
35	func setupStartRequestLedger(t *testing.T, dir string) []byte {
36		t.Helper()
37		s, err := Open(dir)
38		if err != nil {
39			t.Fatalf("Open 失败: %v", err)
40		}
41		registerReplayRecipes(t, s) // R1/v1：M1=0.125、M2=0.5；R1/v2：M1=250、M4=2
42		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 5); err != nil {
43			t.Fatal(err)
44		}
45		if _, err := s.UpdateDraftBatch("u-final", "B1", "R1", "v2", 3); err != nil {
46			t.Fatal(err)
47		}
48		if _, err := s.StartBatch("start-b1", "B1"); err != nil {
49			t.Fatal(err)
50		}
51		base := replayFeedTime()
52		if _, err := s.AddFeeding("f1", "B1", "M1", "100.5", base, "张三"); err != nil {
53			t.Fatal(err)
54		}
55		if _, err := s.AddFeeding("f2", "B1", "M4", "2", base, "李四"); err != nil {
56			t.Fatal(err)
57		}
58		if _, err := s.CloseBatch("close-b1", "B1"); err != nil {
59			t.Fatal(err)
60		}
61		// B2：最终配方与份数和 B1 相同，仅批次编号与请求编号不同。
62		if _, err := s.CreateBatch("b2", "B2", "R1", "v2", 3); err != nil {
63			t.Fatal(err)
64		}
65		if _, err := s.StartBatch("start-b2", "B2"); err != nil {
66			t.Fatal(err)
67		}
68		// B3：执行中、无投料的正常批次。
69		if _, err := s.CreateBatch("b3", "B3", "R1", "v1", 2); err != nil {
70			t.Fatal(err)
71		}
72		if _, err := s.StartBatch("start-b3", "B3"); err != nil {
73			t.Fatal(err)
74		}
75		if err := s.Close(); err != nil {
76			t.Fatal(err)
77		}
78		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
79		if err != nil {
80			t.Fatal(err)
81		}
82		return good
83	}
84	
85	// startResultRaw 取出正常台账中 reqNo 请求的保存结果原文。
86	func startResultRaw(t *testing.T, good []byte, reqNo string) json.RawMessage {
87		t.Helper()
88		var st persistedState
89		if err := json.Unmarshal(good, &st); err != nil {
90			t.Fatal(err)
91		}
92		req := st.Requests[reqNo]
93		if req == nil {
94			t.Fatalf("正常台账中应存在 %s 请求记录", reqNo)
95		}
96		return req.Result
97	}
98	
99	// mutatedStartView 读出 start-b1 的保存结果，按 edit 修改后重新序列化。
100	func mutatedStartView(t *testing.T, good []byte, edit func(*BatchView)) json.RawMessage {
101		t.Helper()
102		var v BatchView
103		if err := json.Unmarshal(startResultRaw(t, good, "start-b1"), &v); err != nil {
104			t.Fatal(err)
105		}
106		edit(&v)
107		raw, err := json.Marshal(v)
108		if err != nil {
109			t.Fatal(err)
110		}
111		return raw
112	}
113	
114	// corruptStartRequestResult 把正常台账内容中 start-b1 请求的保存结果替换为
115	// mutate 给出的值（mutate 返回 nil 表示删除该字段），返回改写后的文件内容。
116	func corruptStartRequestResult(t *testing.T, good []byte, mutate func() json.RawMessage) []byte {
117		t.Helper()
118		var st persistedState
119		if err := json.Unmarshal(good, &st); err != nil {
120			t.Fatal(err)
121		}
122		req := st.Requests["start-b1"]
123		if req == nil {
124			t.Fatalf("正常台账中应存在 start-b1 请求记录")
125		}
126		req.Result = mutate()
127		data, err := json.MarshalIndent(&st, "", "  ")
128		if err != nil {
129			t.Fatal(err)
130		}
131		return data
132	}
133	
134	// 已保存的成功开始执行请求的结果缺失、为 null、为空对象、无法读成批次结果，
135	// 或与原请求所指批次第一次开始时的内容不一致（批次编号、配方绑定、计划份数、
136	// 状态、投料列表、逐物料应投量/实投量/差额有任何差异，含被另一批次的结果
137	// 顶替、混入后来的投料或关闭现状）时，Open 必须返回 ErrCorruptData：错误
138	// 信息指出问题请求编号及关联批次，不返回可用的台账对象，也不改写原文件。
139	func TestOpenRejectsCorruptStartRequestResult(t *testing.T) {
140		cases := []struct {
141			name   string
142			mutate func(good []byte) json.RawMessage
143		}{
144			{"结果缺失", func(good []byte) json.RawMessage { return nil }},
145			{"结果为 null", func(good []byte) json.RawMessage { return json.RawMessage("null") }},
146			{"结果为空对象", func(good []byte) json.RawMessage { return json.RawMessage(`{}`) }},
147			{"结果不是批次结果对象", func(good []byte) json.RawMessage { return json.RawMessage(`"not-an-object"`) }},
148			{"结果被替换成另一批次的开始结果", func(good []byte) json.RawMessage {
149				// B2 的最终配方、份数与 B1 相同，但那是另一批次的开始结果。
150				return startResultRaw(t, good, "start-b2")
151			}},
152			{"结果批次编号被改成另一批次", func(good []byte) json.RawMessage {
153				return mutatedStartView(t, good, func(v *BatchView) { v.BatchNo = "B2" })
154			}},
155			{"结果配方编号与批次绑定不符", func(good []byte) json.RawMessage {
156				return mutatedStartView(t, good, func(v *BatchView) { v.RecipeNo = "RX" })
157			}},
158			{"结果沿用创建草稿时的旧版本", func(good []byte) json.RawMessage {
159				return mutatedStartView(t, good, func(v *BatchView) { v.RecipeVersion = "v1" })
160			}},
161			{"结果配方名称与批次绑定不符", func(good []byte) json.RawMessage {
162				return mutatedStartView(t, good, func(v *BatchView) { v.RecipeName = "被改的名称" })
163			}},
164			{"结果沿用创建草稿时的旧份数", func(good []byte) json.RawMessage {
165				return mutatedStartView(t, good, func(v *BatchView) { v.PlannedPortions = 5 })
166			}},
167			{"结果状态被改成关闭后的现状", func(good []byte) json.RawMessage {
168				return mutatedStartView(t, good, func(v *BatchView) { v.Status = StatusClosed })
169			}},
170			{"结果混入了后来追加的投料", func(good []byte) json.RawMessage {
171				return mutatedStartView(t, good, func(v *BatchView) {
172					base := replayFeedTime()
173					v.Feedings = []FeedingView{
174						{Seq: 1, MaterialNo: "M1", Grams: "100.5", Time: base, Registrar: "张三"},
175						{Seq: 2, MaterialNo: "M4", Grams: "2", Time: base, Registrar: "李四"},
176					}
177				})
178			}},
179			{"物料核对项少一项", func(good []byte) json.RawMessage {
180				return mutatedStartView(t, good, func(v *BatchView) {
181					v.Materials = v.Materials[:1]
182				})
183			}},
184			{"物料核对项混入旧版本的物料", func(good []byte) json.RawMessage {
185				return mutatedStartView(t, good, func(v *BatchView) {
186					v.Materials = append(v.Materials, MaterialRequirement{
187						MaterialNo: "M2", RequiredGrams: "1.5", ActualGrams: "0", DifferenceGrams: "-1.5",
188					})
189				})
190			}},
191			{"物料核对顺序被调换", func(good []byte) json.RawMessage {
192				return mutatedStartView(t, good, func(v *BatchView) {
193					v.Materials[0], v.Materials[1] = v.Materials[1], v.Materials[0]
194				})
195			}},
196			{"应投量被改成旧计划的值", func(good []byte) json.RawMessage {
197				return mutatedStartView(t, good, func(v *BatchView) { v.Materials[0].RequiredGrams = "0.625" })
198			}},
199			{"实投量被改成非零", func(good []byte) json.RawMessage {
200				return mutatedStartView(t, good, func(v *BatchView) { v.Materials[0].ActualGrams = "100.5" })
201			}},
202			{"差额被改坏", func(good []byte) json.RawMessage {
203				return mutatedStartView(t, good, func(v *BatchView) { v.Materials[0].DifferenceGrams = "0" })
204			}},
205		}
206		for _, tc := range cases {
207			t.Run(tc.name, func(t *testing.T) {
208				dir := t.TempDir()
209				good := setupStartRequestLedger(t, dir)
210				bad := corruptStartRequestResult(t, good, func() json.RawMessage { return tc.mutate(good) })
211				if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
212					t.Fatal(err)
213				}
214	
215				s, err := Open(dir)
216				if !errors.Is(err, ErrCorruptData) {
217					t.Fatalf("保存的开始结果损坏应返回 ErrCorruptData，得到 %v", err)
218				}
219				if s != nil {
220					s.Close()
221					t.Fatalf("损坏台账不应返回可用的 Store 对象")
222				}
223				msg := err.Error()
224				for _, want := range []string{"start-b1", "B1"} {
225					if !strings.Contains(msg, want) {
226						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
227					}
228				}
229				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
230				if err != nil {
231					t.Fatal(err)
232				}
233				if !bytes.Equal(got, bad) {
234					t.Fatalf("拒绝打开不应改动台账文件")
235				}
236			})
237		}
238	}
239	
240	// 原请求所指的批次不存在时，保存的开始结果不能单独作为开始成功的依据：
241	// 即使结果本身内容完整，也按损坏处理。
242	func TestOpenRejectsStartRequestResultWhenBatchMissing(t *testing.T) {
243		dir := t.TempDir()
244		good := setupStartRequestLedger(t, dir)
245		var st persistedState
246		if err := json.Unmarshal(good, &st); err != nil {
247			t.Fatal(err)
248		}
249		// 删除 B1（start-b1、close-b1 及 f1、f2 对应的批次），保留完整的 B2、B3。
250		kept := st.Batches[:0]
251		for _, b := range st.Batches {
252			if b.BatchNo != "B1" {
253				kept = append(kept, b)
254			}
255		}
256		st.Batches = kept
257		bad, err := json.MarshalIndent(&st, "", "  ")
258		if err != nil {
259			t.Fatal(err)
260		}
261		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
262			t.Fatal(err)
263		}
264	
265		s, err := Open(dir)
266		if !errors.Is(err, ErrCorruptData) {
267			t.Fatalf("原批次不存在但保留开始结果应返回 ErrCorruptData，得到 %v", err)
268		}
269		if s != nil {
270			s.Close()
271			t.Fatalf("损坏台账不应返回可用的 Store 对象")
272		}
273		if !strings.Contains(err.Error(), "B1") {
274			t.Fatalf("错误信息应指出关联批次 B1，得到 %v", err)
275		}
276		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
277		if err != nil {
278			t.Fatal(err)
279		}
280		if !bytes.Equal(got, bad) {
281			t.Fatalf("拒绝打开不应改动台账文件")
282		}
283	}
284	
285	// 原请求所指的批次当前只能是执行中或已关闭：批次被改回草稿时，保存的开始
286	// 结果与已确认记录不再一致，按损坏处理。
287	func TestOpenRejectsStartRequestResultWhenBatchBackToDraft(t *testing.T) {
288		dir := t.TempDir()
289		good := setupStartRequestLedger(t, dir)
290		var st persistedState
291		if err := json.Unmarshal(good, &st); err != nil {
292			t.Fatal(err)
293		}
294		for _, b := range st.Batches {
295			if b.BatchNo == "B1" {
296				b.Status = StatusDraft
297				b.Feedings = nil // 草稿带投料本身即损坏，这里只针对状态回退
298			}
299		}
300		// 批次被改回草稿后，后来的投料与关闭请求记录也随之失去对应记录，
301		// 一并移除，让开始请求的状态回退成为唯一的损坏点。
302		delete(st.Requests, "f1")
303		delete(st.Requests, "f2")
304		delete(st.Requests, "close-b1")
305		bad, err := json.MarshalIndent(&st, "", "  ")
306		if err != nil {
307			t.Fatal(err)
308		}
309		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
310			t.Fatal(err)
311		}
312	
313		s, err := Open(dir)
314		if !errors.Is(err, ErrCorruptData) {
315			t.Fatalf("批次被改回草稿应返回 ErrCorruptData，得到 %v", err)
316		}
317		if s != nil {
318			s.Close()
319			t.Fatalf("损坏台账不应返回可用的 Store 对象")
320		}
321		msg := err.Error()
322		for _, want := range []string{"start-b1", "B1"} {
323			if !strings.Contains(msg, want) {
324				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
325			}
326		}
327		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
328		if err != nil {
329			t.Fatal(err)
330		}
331		if !bytes.Equal(got, bad) {
332			t.Fatalf("拒绝打开不应改动台账文件")
333		}
334	}
335	
336	// 正常写法差异不能误判为损坏：保存结果的应投量写成 750.000、实投量写成
337	// 0.000、差额写成 -750.000，与首次开始时的数量是同一数值；合法的零实投与
338	// 负差额不是损坏。台账应正常打开，重放仍返回保存的写法。
339	func TestOpenAcceptsStartRequestResultFormatVariants(t *testing.T) {
340		dir := t.TempDir()
341		good := setupStartRequestLedger(t, dir)
342	
343		bad := corruptStartRequestResult(t, good, func() json.RawMessage {
344			return mutatedStartView(t, good, func(v *BatchView) {
345				v.Materials[0].RequiredGrams = "750.000" // 与 750 是同一数量
346				v.Materials[0].ActualGrams = "0.000"     // 与 0 是同一数量
347				v.Materials[0].DifferenceGrams = "-750.000"
348				v.Materials[1].RequiredGrams = "6.000"
349			})
350		})
351		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
352			t.Fatal(err)
353		}
354	
355		s, err := Open(dir)
356		if err != nil {
357			t.Fatalf("写法差异不应判为损坏: %v", err)
358		}
359		defer s.Close()
360	
361		// 重放取回保存的结果原文：核对项保持 750.000、0.000、-750.000 写法，
362		// 但与首次开始时的数量是同一数值。
363		replay, err := s.StartBatch("start-b1", "B1")
364		if err != nil {
365			t.Fatalf("重放开始请求应成功: %v", err)
366		}
367		if replay.Materials[0].RequiredGrams != "750.000" ||
368			replay.Materials[0].ActualGrams != "0.000" ||
369			replay.Materials[0].DifferenceGrams != "-750.000" {
370			t.Fatalf("重放应返回保存的核对项写法，得到 %+v", replay.Materials[0])
371		}
372		// 批次后来的投料与关闭属于现状：查询显示已关闭与当前投料，不影响
373		// 首次开始结果的合法性。
374		checkClosedCurrentAfterSetup(t, mustGetBatch(t, s, "B1"))
375	}
376	
377	// checkClosedCurrentAfterSetup 校验 setupStartRequestLedger 中 B1 的当前
378	// 台账记录：已关闭、R1/v2、3 份，保留 f1、f2 两条投料。
379	func checkClosedCurrentAfterSetup(t *testing.T, v *BatchView) {
380		t.Helper()
381		if v.BatchNo != "B1" || v.Status != StatusClosed || v.PlannedPortions != 3 ||
382			v.RecipeNo != "R1" || v.RecipeVersion != "v2" {
383			t.Fatalf("当前台账应为已关闭的 R1/v2、3 份，得到 %+v", v)
384		}
385		if len(v.Feedings) != 2 {
386			t.Fatalf("当前台账应保留 2 条投料，得到 %d 条", len(v.Feedings))
387		}
388		mats := materialsMap(v)
389		checkRequirement(t, mats, "M1", "750", "100.5", "-649.5")
390		checkRequirement(t, mats, "M4", "6", "2", "-4")
391	}
392	
393	// 批次后来追加的投料与关闭状态属于批次现状，不能混入第一次开始的结果，
394	// 也不能成为拒绝合法旧结果的理由：台账中 B1 已投料并关闭，其保存的开始
395	// 结果仍是首次开始时的内容（执行中、空投料、零实投），打开与重放都必须
396	// 正常。
397	func TestStartRequestResultStaysFirstStartAfterFeedingAndClose(t *testing.T) {
398		dir := t.TempDir()
399		setupStartRequestLedger(t, dir)
400	
401		s, err := Open(dir)
402		if err != nil {
403			t.Fatalf("已投料并关闭的批次不应让其首次开始结果被判损坏: %v", err)
404		}
405		defer s.Close()
406	
407		replay, err := s.StartBatch("start-b1", "B1")
408		if err != nil {
409			t.Fatalf("重放开始请求应成功: %v", err)
410		}
411		checkFirstStartView(t, replay)
412		checkClosedCurrentAfterSetup(t, mustGetBatch(t, s, "B1"))
413	}
414	
415	// 台账正常打开后，保存内容中的开始请求结果被改坏：下一次查询或写入必须
416	// 返回 ErrCorruptData——即使本次访问的是另一个正常批次，也不能忽略损坏的
417	// 开始请求；被拒绝的重放不得返回损坏的保存结果，被拒绝的写入不留业务变化、
418	// 不占用请求编号，原台账内容不变。恢复后原成功请求仍可幂等重放，被拒绝过
419	// 的请求编号可以正常使用。
420	func TestStartRequestResultCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
421		dir := t.TempDir()
422		good := setupStartRequestLedger(t, dir)
423	
424		s, err := Open(dir)
425		if err != nil {
426			t.Fatal(err)
427		}
428		defer s.Close()
429	
430		// 打开后把 start-b1 的保存结果改坏为空对象（其余记录保持完整）。
431		bad := corruptStartRequestResult(t, good, func() json.RawMessage {
432			return json.RawMessage(`{}`)
433		})
434		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
435			t.Fatal(err)
436		}
437	
438		// 查询损坏批次与正常批次都必须失败，不能沿用此前读到的内容。
439		for _, batchNo := range []string{"B1", "B3"} {
440			if v, err := s.GetBatch(batchNo); !errors.Is(err, ErrCorruptData) {
441				t.Fatalf("查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
442			} else if v != nil {
443				t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
444			}
445		}
446		// 用原编号、原内容重放损坏的开始请求：不得把损坏的保存结果当成成功
447		// 结果返回，必须报损坏。
448		if _, err := s.StartBatch("start-b1", "B1"); !errors.Is(err, ErrCorruptData) {
449			t.Fatalf("重放损坏的开始请求应返回 ErrCorruptData，得到 %v", err)
450		}
451		// 对正常批次的新写入同样不能绕过。
452		if _, err := s.CloseBatch("close-b3", "B3"); !errors.Is(err, ErrCorruptData) {
453			t.Fatalf("损坏台账上关闭正常批次应返回 ErrCorruptData，得到 %v", err)
454		}
455	
456		// 被拒绝的访问不改动文件、不占用请求编号。
457		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
458		if err != nil {
459			t.Fatal(err)
460		}
461		if !bytes.Equal(after, bad) {
462			t.Fatalf("被拒绝的访问不应改动台账文件")
463		}
464		if bytes.Contains(after, []byte("close-b3")) {
465			t.Fatalf("被拒绝的写入不应留下请求记录")
466		}
467	
468		// 恢复后：原成功请求仍取回第一次开始时的结果，被拒绝过的请求编号
469		// 可以正常使用。
470		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
471			t.Fatal(err)
472		}
473		replay, err := s.StartBatch("start-b1", "B1")
474		if err != nil {
475			t.Fatalf("恢复后重放原成功请求失败: %v", err)
476		}
477		checkFirstStartView(t, replay)
478		closed, err := s.CloseBatch("close-b3", "B3")
479		if err != nil {
480			t.Fatalf("被拒绝过的请求编号应仍可合法提交: %v", err)
481		}
482		if closed.Status != StatusClosed || closed.BatchNo != "B3" {
483			t.Fatalf("B3 应被正常关闭，得到 %+v", closed)
484		}
485	}
