75		if v.PlannedPortions != 8 {
76			t.Fatalf("计划份数应为最初创建的 8，得到 %d", v.PlannedPortions)
77		}
78		if v.Status != StatusDraft {
79			t.Fatalf("最初创建的结果应为草稿，得到 %s", v.Status)
80		}
81		if len(v.Feedings) != 0 {
82			t.Fatalf("最初创建时投料列表应为空，得到 %d 条: %+v", len(v.Feedings), v.Feedings)
83		}
84		if len(v.Materials) != 2 {
85			t.Fatalf("最初版本只有 M1、M2 两种物料，得到 %d 项: %+v", len(v.Materials), v.Materials)
86		}
87		// 物料顺序必须与最初版本一致，不能被后来版本的物料列表带跑。
88		if v.Materials[0].MaterialNo != "M1" || v.Materials[1].MaterialNo != "M2" {
89			t.Fatalf("物料顺序应与 R1/v1 一致（M1、M2），得到 %+v", v.Materials)
90		}
91		mats := materialsMap(v)
92		checkRequirement(t, mats, "M1", "1", "0", "-1")       // 0.125 × 8，精确为 1
93		checkRequirement(t, mats, "M2", "0.008", "0", "-0.008") // 0.001 × 8，千分之一克精度
94		if _, leftover := mats["M4"]; leftover {
95			t.Fatalf("重放创建结果不能带入新版本独有的物料 M4: %+v", mats["M4"])
96		}
97	}
98	
99	// checkAdjustedCurrent 校验 B1 调整为 R1/v2、3 份之后的“当前台账记录”：
100	// 查询在任何重放前后都必须保持这个结果，不能被历史创建结果回退。
101	func checkAdjustedCurrent(t *testing.T, v *BatchView) {
102		t.Helper()
103		if v.BatchNo != "B1" || v.RecipeNo != "R1" || v.RecipeVersion != "v2" ||
104			v.RecipeName != "配方改版" || v.PlannedPortions != 3 || v.Status != StatusDraft {
105			t.Fatalf("当前批次应保留调整后的计划（R1/v2、配方改版、3 份、草稿），得到 %+v", v)
106		}
107		if len(v.Feedings) != 0 {
108			t.Fatalf("当前草稿不应有投料，得到 %d 条: %+v", len(v.Feedings), v.Feedings)
109		}
110		if len(v.Materials) != 2 {
111			t.Fatalf("当前计划只应有 M1、M4 两种物料，得到 %d 项: %+v", len(v.Materials), v.Materials)
112		}
113		if v.Materials[0].MaterialNo != "M1" || v.Materials[1].MaterialNo != "M4" {
114			t.Fatalf("物料顺序应与 R1/v2 一致（M1、M4），得到 %+v", v.Materials)
115		}
116		mats := materialsMap(v)
117		checkRequirement(t, mats, "M1", "750", "0", "-750") // 250 × 3，不是创建时的 0.125 × 8
118		checkRequirement(t, mats, "M4", "6", "0", "-6")     // 2 × 3
119		if _, leftover := mats["M2"]; leftover {
120			t.Fatalf("当前计划不应残留旧版本物料 M2: %+v", mats["M2"])
121		}
122	}
123	
124	// 创建草稿 → 正常调整配方版本与份数 → 用原请求编号和原创建内容重复提交：
125	// 每次重放都返回第一次创建成功时的完整结果（含按最初版本、最初份数的
126	// 数量核对），既不因批次编号已存在被拒绝，也不把当前计划回退成创建时的
127	// 内容；台账始终只有一个批次，原创建请求记录不被新增或替换。
128	// 重新打开台账后，重放与查询仍各自反映应有的内容。
129	func TestCreateBatchReplayAfterDraftAdjustReturnsFirstResult(t *testing.T) {
130		dir := t.TempDir()
131		s, err := Open(dir)
132		if err != nil {
133			t.Fatalf("Open 失败: %v", err)
134		}
135		registerCreateReplayRecipes(t, s)
136	
137		first, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
138		if err != nil {
139			t.Fatalf("首次创建批次应成功: %v", err)
140		}
141		checkFirstCreateView(t, first)
142	
143		// 随后正常调整这个批次的配方版本及份数。
144		adj, err := s.UpdateDraftBatch("adjust-b1", "B1", "R1", "v2", 3)
145		if err != nil {
146			t.Fatalf("调整草稿应成功: %v", err)
147		}
148		if adj.RecipeNo != "R1" || adj.RecipeVersion != "v2" || adj.PlannedPortions != 3 ||
149			adj.Status != StatusDraft {
150			t.Fatalf("调整结果应为 R1/v2、3 份的草稿，得到 %+v", adj)
151		}
152	
153		// 重复提交前，查询看到的就是调整后的计划。
154		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
155	
156		// 用原请求编号与原创建内容重复提交：必须返回第一次创建成功的完整结果，
157		// 不能返回 ErrDuplicateBatch（由 err == nil 直接保证），
158		// 也不能被当成一次新的计划调整。
159		replay, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
160		if err != nil {
161			t.Fatalf("草稿调整后重放原创建请求应成功返回首次结果: %v", err)
162		}
163		checkFirstCreateView(t, replay)
164		// 重放之后查询：当前批次仍保留后来调整的计划，没有被回退。
165		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
166	
167		// 再查询与再重放交替进行：历史结果始终是创建时的结果，查询始终是当前计划。
168		replay2, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
169		if err != nil {
170			t.Fatalf("再次重放原创建请求应成功: %v", err)
171		}
172		checkFirstCreateView(t, replay2)
173		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
174	
175		// 白盒核对：多次重放后台账始终只有一个批次；原创建请求记录仍在，
176		// 操作类型、载荷与保存的结果都还是第一次创建时的内容，没有被重放
177		// 新增或替换成调整后的结果。
178		if err := s.read(func(st *persistedState) error {
179			if len(st.Batches) != 1 {
180				t.Fatalf("重放不应新增批次，应始终只有 1 个，得到 %d 个", len(st.Batches))
181			}
182			req := st.Requests["create-b1"]
183			if req == nil {
184				t.Fatal("原创建请求记录丢失")
185			}
186			if req.Op != opCreateBatch {
187				t.Fatalf("原创建请求的操作类型被改写，得到 %q", req.Op)
188			}
189			var payload createBatchPayload
190			if err := json.Unmarshal([]byte(req.Payload), &payload); err != nil {
191				t.Fatalf("原创建请求载荷无法解析: %v", err)
192			}
193			if payload != (createBatchPayload{BatchNo: "B1", RecipeNo: "R1", Version: "v1", Portions: 8}) {
194				t.Fatalf("原创建请求载荷被改写，得到 %+v", payload)
195			}
196			var saved BatchView
197			if err := json.Unmarshal(req.Result, &saved); err != nil {
198				t.Fatalf("原创建请求保存的结果无法解析: %v", err)
199			}
200			if saved.RecipeNo != "R1" || saved.RecipeVersion != "v1" ||
201				saved.RecipeName != "配方初版" || saved.PlannedPortions != 8 ||
202				saved.Status != StatusDraft {
203				t.Fatalf("保存的创建结果被后来的调整污染: %+v", saved)
204			}
205			return nil
206		}); err != nil {
207			t.Fatalf("读取台账内部状态失败: %v", err)
208		}
209	
210		// 重新打开台账后：重放仍返回第一次创建的结果，查询仍显示调整后的计划。
211		if err := s.Close(); err != nil {
212			t.Fatalf("关闭台账失败: %v", err)
213		}
214		s2, err := Open(dir)
215		if err != nil {
216			t.Fatalf("重新打开台账失败: %v", err)
217		}
218		t.Cleanup(func() { s2.Close() })
219	
220		replayAfterReopen, err := s2.CreateBatch("create-b1", "B1", "R1", "v1", 8)
221		if err != nil {
222			t.Fatalf("重新打开后重放原创建请求应成功: %v", err)
223		}
224		checkFirstCreateView(t, replayAfterReopen)
225		checkAdjustedCurrent(t, mustGetBatch(t, s2, "B1"))
226	}
227	
228	// 调用方改写首次创建返回对象或重放返回对象中的配方信息、份数、状态、
229	// 投料列表与物料核对项，只能影响它自己持有的结果：下一次重放仍返回原
230	// 创建结果，查询仍返回当前调整后的计划，两个结果的物料列表不能相互影响。
231	func TestCreateBatchReplayResultIsCallerOwnedCopy(t *testing.T) {
232		s := openTestStore(t)
233		registerCreateReplayRecipes(t, s)
234	
235		first, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
236		if err != nil {
237			t.Fatalf("首次创建批次应成功: %v", err)
238		}
239		checkFirstCreateView(t, first)
240		if _, err := s.UpdateDraftBatch("adjust-b1", "B1", "R1", "v2", 3); err != nil {
241			t.Fatalf("调整草稿应成功: %v", err)
242		}
243	
244		// 污染调用方持有的首次返回对象：配方信息、份数、状态、投料、物料核对，
245		// 再追加伪造项。
246		first.RecipeNo = "RX"
247		first.RecipeVersion = "v9"
248		first.RecipeName = "被污染的名称"
249		first.PlannedPortions = 99
250		first.Status = StatusClosed
251		first.Feedings = append(first.Feedings, FeedingView{
252			Seq: 1, MaterialNo: "FAKE", Grams: "999", Registrar: "外人",
253		})
254		first.Materials[0].RequiredGrams = "1"
255		first.Materials[0].ActualGrams = "999"
256		first.Materials[0].DifferenceGrams = "998"
257		first.Materials = append(first.Materials, MaterialRequirement{MaterialNo: "FAKE"})
258	
259		// 再提交同一创建请求：重放结果必须仍是干净的首次创建结果。
260		replay, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
261		if err != nil {
262			t.Fatalf("污染首次返回对象后重放应成功: %v", err)
263		}
264		checkFirstCreateView(t, replay)
265		// 查询不受污染：仍是调整后的当前计划。
266		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
267	
268		// 再污染重放对象，第二轮重放与查询仍各自干净，两份结果的物料列表互不相干。
269		replay.Status = StatusClosed
270		replay.PlannedPortions = 77
271		replay.Materials[0].ActualGrams = "42"
272		replay.Feedings = append(replay.Feedings, FeedingView{Seq: 2, MaterialNo: "FAKE2"})
273		replay2, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
274		if err != nil {
275			t.Fatalf("污染重放对象后再次重放应成功: %v", err)
276		}
277		checkFirstCreateView(t, replay2)
278		// 上一份重放对象的污染不能进入这一份结果。
279		if replay2.Materials[0].ActualGrams != "0" || len(replay2.Feedings) != 0 {
280			t.Fatalf("两次重放结果的物料列表相互影响了: %+v", replay2)
281		}
282		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
283	}
284	
285	// 区分重复提交与请求冲突、批次重复：
286	//   - 沿用原创建请求编号、却改变创建内容中的批次编号、配方编号、版本号或
287	//     份数，一律返回 ErrRequestConflict；即使改后的内容恰好等于当前草稿
288	//     计划，也不能接受为原请求。每个改动本身都是合法的创建内容，不靠
289	//     非法输入被拒来冒充冲突；
290	//   - 换一个未使用的请求编号创建同编号批次，仍返回 ErrDuplicateBatch
291	//     （即使内容与当前草稿计划完全一致）；
292	//   - 两类拒绝都不改动当前批次、不创建旁支批次，也不替换原请求的成功结果；
293	//   - 被拒绝的新编号没有被失败占用，修正为创建尚不存在的批次后仍可成功。
294	func TestCreateBatchReplayDistinguishesConflictAndDuplicate(t *testing.T) {
295		s := openTestStore(t)
296		registerCreateReplayRecipes(t, s)
297		// 另一个真实存在的配方版本，供“改配方编号”场景使用，使改后内容本身合法。
298		if _, err := s.RegisterRecipe("c-recipe-r2", "R2", "v1", "另一配方", []MaterialInput{
299			{MaterialNo: "M5", Grams: "1"},
300		}); err != nil {
301			t.Fatalf("登记 R2/v1 失败: %v", err)
302		}
303	
304		if _, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8); err != nil {
305			t.Fatalf("首次创建批次应成功: %v", err)
306		}
307		if _, err := s.UpdateDraftBatch("adjust-b1", "B1", "R1", "v2", 3); err != nil {
308			t.Fatalf("调整草稿应成功: %v", err)
309		}
310		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
311	
312		// 沿用原请求编号、只改创建内容中的一项，全部必须判 ErrRequestConflict。
313		conflictCases := []struct {
314			name     string
315			batchNo  string
316			recipeNo string
317			version  string
318			portions int
319		}{
320			// 改批次编号：B2 尚不存在，若无请求记录这本是一次合法创建。
321			{"改批次编号", "B2", "R1", "v1", 8},
322			// 改配方编号：R2/v1 已登记；若无请求记录这本会因 B1 已存在而得到
323			// ErrDuplicateBatch——请求冲突必须先于批次重复判定。
324			{"改配方编号", "B1", "R2", "v1", 8},
325			// 改版本号：R1/v2 已登记，份数沿用，改后是“当前版本 + 旧份数”。
326			{"改版本号", "B1", "R1", "v2", 8},
327			// 改份数：版本沿用，改后是“旧版本 + 当前份数”。
328			{"改份数", "B1", "R1", "v1", 3},
329			// 批次、版本、份数恰好等于当前草稿调整后的计划：也不能接受为原请求。
330			{"改后内容恰好等于当前草稿计划", "B1", "R1", "v2", 3},
331		}
332		for _, tc := range conflictCases {
333			t.Run(tc.name, func(t *testing.T) {
334				_, err := s.CreateBatch("create-b1", tc.batchNo, tc.recipeNo, tc.version, tc.portions)
335				if !errors.Is(err, ErrRequestConflict) {
336					t.Fatalf("沿用原请求编号改变创建内容（%s）应返回 ErrRequestConflict，得到 %v",
337						tc.name, err)
338				}
339			})
340		}
341	
342		// 冲突提交不能创建旁支批次：B2 始终不存在。
343		if _, err := s.GetBatch("B2"); !errors.Is(err, ErrNotFound) {
344			t.Fatalf("冲突提交不应创建 B2，查询应返回 ErrNotFound，得到 %v", err)
345		}
346		// 冲突提交不能改动当前批次：仍是调整后的 R1/v2、3 份草稿。
347		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
348	
349		// 换用未使用的请求编号创建同编号批次：不是重放，批次编号已存在，
350		// 必须返回 ErrDuplicateBatch——即使提交内容与当前草稿计划完全一致。
351		if _, err := s.CreateBatch("create-fresh", "B1", "R1", "v1", 8); !errors.Is(err, ErrDuplicateBatch) {
352			t.Fatalf("新请求编号创建已存在批次应返回 ErrDuplicateBatch，得到 %v", err)
353		}
354		if _, err := s.CreateBatch("create-fresh-same", "B1", "R1", "v2", 3); !errors.Is(err, ErrDuplicateBatch) {
355			t.Fatalf("内容与当前计划一致的新请求仍应返回 ErrDuplicateBatch，得到 %v", err)
356		}
357	
358		// 两类拒绝都不改动当前批次。
359		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
360	
361		// 原创建请求的成功结果不被任何拒绝替换：仍可取回最初创建的完整结果。
362		replay, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
363		if err != nil {
364			t.Fatalf("拒绝后原创建请求仍应可重放: %v", err)
365		}
366		checkFirstCreateView(t, replay)
367		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
368	
369		// 业务失败不占用新请求编号：duplicate 失败后，同一编号改用于创建尚不
370		// 存在的 B3（合法内容）应成功，且 B3 是独立草稿，不影响 B1 的当前计划。
371		b3, err := s.CreateBatch("create-fresh", "B3", "R1", "v1", 8)
372		if err != nil {
373			t.Fatalf("失败不应占用请求编号，改创建 B3 应成功: %v", err)
374		}
375		if b3.BatchNo != "B3" || b3.RecipeVersion != "v1" || b3.PlannedPortions != 8 ||
376			b3.Status != StatusDraft || len(b3.Feedings) != 0 {
377			t.Fatalf("B3 应为独立的 R1/v1、8 份草稿，得到 %+v", b3)
378		}
379		b3Mats := materialsMap(b3)
380		if len(b3Mats) != 2 {
381			t.Fatalf("B3 应按 R1/v1 列出 2 种物料，得到 %d 项: %+v", len(b3Mats), b3.Materials)
382		}
383		checkRequirement(t, b3Mats, "M1", "1", "0", "-1")
384		checkRequirement(t, b3Mats, "M2", "0.008", "0", "-0.008")
385		if _, has := b3Mats["M4"]; has {
386			t.Fatalf("B3 使用 v1，不应带入 v2 独有的 M4: %+v", b3Mats["M4"])
387		}
388		// B1 的当前计划不受 B3 创建影响。
389		checkAdjustedCurrent(t, mustGetBatch(t, s, "B1"))
390	}
391

