175	func TestDraftUpdate(t *testing.T) {
176		s := openTestStore(t)
177		registerStandardRecipe(t, s, "recipe-1")
178		if _, err := s.RegisterRecipe("recipe-2", "R2", "v1", "配方二", []MaterialInput{
179			{MaterialNo: "M1", Grams: "2"},
180		}); err != nil {
181			t.Fatal(err)
182		}
183		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
184			t.Fatal(err)
185		}
186	
187		// 草稿可以改份数。
188		view, err := s.UpdateDraftBatch("u1", "B1", "", "", 20)
189		if err != nil {
190			t.Fatalf("调整份数失败: %v", err)
191		}
192		if view.PlannedPortions != 20 {
193			t.Fatalf("份数应为 20，得到 %d", view.PlannedPortions)
194		}
195		// 草稿可以改选配方版本。
196		view, err = s.UpdateDraftBatch("u2", "B1", "R2", "v1", 0)
197		if err != nil {
198			t.Fatalf("改选配方失败: %v", err)
199		}
200		if view.RecipeNo != "R2" || view.RecipeVersion != "v1" {
201			t.Fatalf("配方应已切换，得到 %+v", view)
202		}
203		// 只给配方编号不给版本号 → 非法。
204		if _, err := s.UpdateDraftBatch("u3", "B1", "R1", "", 0); !errors.Is(err, ErrInvalidInput) {
205			t.Fatalf("只给配方编号应返回 ErrInvalidInput，得到 %v", err)
206		}
207		// 改到不存在的配方版本 → 未找到。
208		if _, err := s.UpdateDraftBatch("u4", "B1", "R9", "v1", 0); !errors.Is(err, ErrNotFound) {
209			t.Fatalf("改到不存在的配方应返回 ErrNotFound，得到 %v", err)
210		}
211		// 份数非法。
212		if _, err := s.UpdateDraftBatch("u5", "B1", "", "", 0); err != nil {
213			t.Fatalf("传 0 应表示不改份数，得到 %v", err)
214		}
215		if _, err := s.UpdateDraftBatch("u6", "B1", "", "", -3); !errors.Is(err, ErrInvalidInput) {
216			t.Fatalf("负份数应返回 ErrInvalidInput，得到 %v", err)
217		}
218		// 不存在的批次。
219		if _, err := s.UpdateDraftBatch("u7", "B9", "", "", 5); !errors.Is(err, ErrNotFound) {
220			t.Fatalf("调整不存在的批次应返回 ErrNotFound，得到 %v", err)
221		}
222	
223		// 开始执行后份数与配方固定。
224		if _, err := s.StartBatch("s1", "B1"); err != nil {
225			t.Fatal(err)
226		}
227		if _, err := s.UpdateDraftBatch("u8", "B1", "", "", 30); !errors.Is(err, ErrInvalidState) {
228			t.Fatalf("执行中调整应返回 ErrInvalidState，得到 %v", err)
229		}
230		if _, err := s.UpdateDraftBatch("u9", "B1", "R1", "v1", 0); !errors.Is(err, ErrInvalidState) {
231			t.Fatalf("执行中改配方应返回 ErrInvalidState，得到 %v", err)
232		}
233		// 关闭后同样不能调整。
234		if _, err := s.CloseBatch("c1", "B1"); err != nil {
235			t.Fatal(err)
236		}
237		if _, err := s.UpdateDraftBatch("u10", "B1", "", "", 30); !errors.Is(err, ErrInvalidState) {
238			t.Fatalf("已关闭批次调整应返回 ErrInvalidState，得到 %v", err)
239		}
240	}
