242	func TestStartCloseLifecycle(t *testing.T) {
243		s := openTestStore(t)
244		registerStandardRecipe(t, s, "recipe-1")
245		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
246			t.Fatal(err)
247		}
248	
249		// 只有草稿可以开始。
250		if _, err := s.CloseBatch("c0", "B1"); !errors.Is(err, ErrInvalidState) {
251			t.Fatalf("关闭草稿应返回 ErrInvalidState，得到 %v", err)
252		}
253		view, err := s.StartBatch("s1", "B1")
254		if err != nil {
255			t.Fatalf("开始执行失败: %v", err)
256		}
257		if view.Status != StatusExecuting {
258			t.Fatalf("状态应为执行中，得到 %s", view.Status)
259		}
260		// 重复开始。
261		if _, err := s.StartBatch("s2", "B1"); !errors.Is(err, ErrInvalidState) {
262			t.Fatalf("重复开始应返回 ErrInvalidState，得到 %v", err)
263		}
264		// 只有执行中可以关闭。
265		view, err = s.CloseBatch("c1", "B1")
266		if err != nil {
267			t.Fatalf("关闭失败: %v", err)
268		}
269		if view.Status != StatusClosed {
270			t.Fatalf("状态应为已关闭，得到 %s", view.Status)
271		}
272		// 关闭后不能再关、不能再开、不能投料、不能改草稿。
273		if _, err := s.CloseBatch("c2", "B1"); !errors.Is(err, ErrInvalidState) {
274			t.Fatalf("重复关闭应返回 ErrInvalidState，得到 %v", err)
275		}
276		if _, err := s.StartBatch("s3", "B1"); !errors.Is(err, ErrInvalidState) {
277			t.Fatalf("关闭后重新打开应返回 ErrInvalidState，得到 %v", err)
278		}
279		if _, err := s.AddFeeding("f1", "B1", "M1", "10", time.Now(), "张三"); !errors.Is(err, ErrInvalidState) {
280			t.Fatalf("关闭后投料应返回 ErrInvalidState，得到 %v", err)
281		}
282		// 不存在的批次。
283		if _, err := s.StartBatch("s4", "B9"); !errors.Is(err, ErrNotFound) {
284			t.Fatalf("开始不存在的批次应返回 ErrNotFound，得到 %v", err)
285		}
286		if _, err := s.CloseBatch("c3", "B9"); !errors.Is(err, ErrNotFound) {
287			t.Fatalf("关闭不存在的批次应返回 ErrNotFound，得到 %v", err)
288		}
289	}
