414			t.Fatal(err)
415		}
416		if _, err := s.AddFeeding("f1", "B1", "M1", "100", time.Now(), "张三"); err != nil {
417			t.Fatal(err)
418		}
419	
420		view, err := s.GetBatch("B1")
421		if err != nil {
422			t.Fatal(err)
423		}
424		view.Status = StatusClosed
425		view.PlannedPortions = 999
426		view.Feedings[0].Grams = "9999"
427		view.Materials[0].ActualGrams = "9999"
428		view.Materials = append(view.Materials, MaterialRequirement{MaterialNo: "FAKE"})
429	
430		again, err := s.GetBatch("B1")
431		if err != nil {
432			t.Fatal(err)
433		}
434		if again.Status != StatusExecuting || again.PlannedPortions != 10 {
435			t.Fatalf("台账被查询结果修改: %+v", again)
436		}
437		if again.Feedings[0].Grams != "100" || again.Materials[0].ActualGrams != "100" {
438			t.Fatalf("台账数据被查询结果修改: %+v", again)
439		}
